// Map a NEXUS lead onto Bitrix24 crm.lead.add field shape.
// Bitrix expects EMAIL/PHONE as arrays of {VALUE, VALUE_TYPE} objects.
const j = $json;
const lead = j.lead || j;
const score = (j.ai_decision && j.ai_decision.score) ?? lead.ai_score ?? 0;

const clean = (v) => (v === undefined || v === null || v === false || v === '') ? null : String(v);
const name = clean(lead.name) || 'Unknown lead';
const interest = clean(lead.vehicle_interest);
const email = clean(lead.email);
const phone = clean(lead.phone);

const fields = {
  TITLE: interest ? name + ' - ' + interest : name + ' - NEXUS OS lead',
  NAME: name,
  OPPORTUNITY: Number(lead.budget_aed) || 0,
  CURRENCY_ID: 'AED',
  SOURCE_DESCRIPTION: clean(lead.source) || 'NEXUS OS',
  COMMENTS: [
    interest ? 'Vehicle interest: ' + interest : null,
    'AI score: ' + score,
    lead.source ? 'Source: ' + lead.source : null,
    email ? 'Email: ' + email : null,
    phone ? 'Phone: ' + phone : null,
    'Synced automatically from NEXUS OS'
  ].filter(Boolean).join('\n')
};

// Only send contact arrays when a value exists - Bitrix rejects empty ones.
if (email) fields.EMAIL = [{ VALUE: email, VALUE_TYPE: 'WORK' }];
if (phone) fields.PHONE = [{ VALUE: phone, VALUE_TYPE: 'WORK' }];

return { json: { fields: fields, params: { REGISTER_SONET_EVENT: 'Y' }, _lead_email: email, _lead_name: name } };

// Bitrix has no upsert: crm.lead.add always creates a new record, so syncing
// twice would duplicate every lead. Look the lead up by email first and decide
// between update and add.
const found = (($json && $json.result) || [])[0] || null;
const mapped = $('Map Lead to Bitrix24 Lead').item.json;
const existingId = found ? Number(found.ID) : null;

// crm.lead.update APPENDS to multi-value fields rather than replacing them, so
// re-syncing an existing lead kept stacking duplicate phone/email entries.
// Contact details are set once at creation; updates only refresh the sales data.
const fields = { ...mapped.fields };
if (existingId) { delete fields.PHONE; delete fields.EMAIL; }

return { json: {
  existing_id: existingId,
  fields: fields,
  params: mapped.params,
  _lead_email: mapped._lead_email,
  _lead_name: mapped._lead_name
} };

// Normalise the Bitrix24 response into an audit row.
const r = $json || {};
const d = $('Decide Update or Create').item.json;
const wasUpdate = !!d.existing_id;
const ok = wasUpdate ? (r.result === true) : !!r.result;

let reason = null;
if (!ok) {
  const raw = r.error ? (r.error.message || JSON.stringify(r.error)) : (r.error_description || r.error || 'unknown error');
  const m = String(raw).match(/\{.*\}/s);
  if (m) { try { const p = JSON.parse(m[0]); reason = p.error_description || p.error || String(raw); } catch (e) { reason = String(raw); } }
  else { reason = String(raw); }
  reason = reason.replace(/\\u0022/g, '"').substring(0, 300);
}

const id = wasUpdate ? d.existing_id : r.result;
return { json: {
  workflow: 'wf_108 ERP Sync - Bitrix24',
  status: ok ? 'SUCCESS' : 'FAILED',
  lead_name: d._lead_name || null,
  lead_email: d._lead_email || null,
  summary: ok
    ? ('Bitrix24 lead ' + (wasUpdate ? 'updated' : 'created') + ' (ID ' + id + ')')
    : ('Bitrix24 lead ' + (wasUpdate ? 'update' : 'creation') + ' failed: ' + reason)
} };

// This node sits ONLY on the public webhook branch.
// 'Called by Master Router' connects straight to the next node and never
// reaches here, so the trusted sub-workflow path is untouched by this guard.
//
// 'Verify JWT' runs with onError = continueRegularOutput, so a rejected token
// arrives as data rather than as a failed HTTP node. Supabase GET
// /auth/v1/user returns the user object on success; no .id means rejected.
const auth = $input.first().json || {};
if (!auth.id) {
  throw new Error('ERP sync rejected: unauthorized. A valid Supabase session token is required in the Authorization header.');
}

// Re-emit the ORIGINAL request untouched so the downstream node sees exactly
// the shape it saw before this guard was inserted.
return $('ErpSyncWebhook').all();

// Verify every node whose success this audit row is about to claim.
// Only ONE of the two Bitrix writes runs for a given lead, so claim the node on
// the branch that actually ran -- $('Node') THROWS for a node that did not run
// and ?. cannot rescue it, so naming the wrong one would report a phantom drop.
// This node is unconditionally on the path, so the lookup cannot actually
// fail -- but this node's whole job is to be the one place that never lies,
// and a Code node that throws takes the audit row down with it.
let d = {};
try { d = $('Decide Update or Create').item.json || {}; } catch (e) { d = {}; }
const wasUpdate = !!d.existing_id;

const CLAIMED = [
  wasUpdate
    ? { node: 'Update Bitrix24 Lead', what: 'Bitrix24 CRM lead update', critical: true }
    : { node: 'Create Bitrix24 Lead', what: 'Bitrix24 CRM lead creation', critical: true },
  // Swallows too. When this lookup drops, existing_id is null, the run takes
  // the create branch and silently duplicates a lead that was already there.
  { node: 'Find Existing Lead', what: 'Bitrix24 duplicate-check lookup', critical: false },
];

function check(c) {
  let it;
  try { it = $(c.node).item; }
  catch (e) { return { ...c, ok: false, why: 'node did not run on this branch' }; }
  if (!it) return { ...c, ok: false, why: 'node produced no items' };
  const j = it.json || {};
  if (j.error !== undefined) {
    const m = j.error && (j.error.message || j.error.description) || j.error;
    return { ...c, ok: false, why: String(m).slice(0, 300) };
  }
  return { ...c, ok: true };
}

const results = CLAIMED.map(check);
const dropped = results.filter(r => !r.ok);
const fatal   = dropped.filter(r => r.critical);

const base = $json;

// 'Build Audit Row' already judges the Bitrix payload itself (result === true,
// or a numeric new ID). A 200 carrying result:false has no `error` key, so keep
// that verdict rather than overriding it upward.
const priorFailed = String(base.status || '').toUpperCase() === 'FAILED';

const status = (fatal.length || priorFailed) ? 'FAILED'
             : dropped.length               ? 'PARTIAL'
             : 'SUCCESS';

const note = dropped.length
  ? dropped.length + ' of ' + results.length + ' claimed steps did not land'
  : 'all ' + results.length + ' claimed steps verified';

// 'Log to Supabase audit_log' inserts with autoMapInputData, so this node must
// emit exactly the columns the row already had -- an extra key would be an
// unknown column and would fail the insert. The delivery verdict therefore
// lands in `status` and `summary` rather than in a nested object.
return { json: {
  workflow:   base.workflow,
  status:     status,
  lead_name:  base.lead_name,
  lead_email: base.lead_email,
  summary:    base.summary + ' | ' + note
              + (dropped.length ? ' [' + dropped.map(r => r.what + ' - ' + r.why).join('; ') + ']' : ''),
} };
